css:
.sentinela-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
    max-width: 1200px;
    margin: 0 auto;
}

.sentinela-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #243352 100%);
    color: #ffffff;
    padding: 28px 32px;
    border-radius: 4px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 3px solid #c9a04d;
}

.sentinela-sim-brand {
    display: flex;
    align-items: center;
    gap: 18px;
}

.sentinela-sim-brand-mark {
    background: #c9a04d;
    color: #1a2744;
    width: 56px;
    height: 56px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 1.2rem;
    letter-spacing: 0.04em;
    border-radius: 4px;
}

.sentinela-sim-brand-text h1 {
    font-size: 1.4rem;
    font-weight: 700;
    margin: 0 0 4px 0;
    letter-spacing: 0.01em;
    color: #ffffff;
}

.sentinela-sim-subtitle {
    color: #7d6229;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 500;
}

.sentinela-sim-roundmeta {
    text-align: right;
}

.sentinela-sim-roundlabel {
    color: #ffffff;
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 6px;
}

.sentinela-sim-clock {
    color: #7d6229;
    font-size: 0.8rem;
    font-style: italic;
}

.sentinela-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 12px;
}

.sentinela-sim-kpi-grid-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 24px;
}

.sentinela-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e1e4ea;
    border-top: 3px solid #1a2744;
    padding: 18px 20px;
    border-radius: 3px;
    transition: box-shadow 0.2s ease;
}

.sentinela-sim-kpi-card:hover {
    box-shadow: 0 4px 12px rgba(26,39,68,0.08);
}

.sentinela-sim-kpi-eva { border-top-color: #1a2744; }
.sentinela-sim-kpi-arch { border-top-color: #2d6a4f; }
.sentinela-sim-kpi-def { border-top-color: #5b3a8a; }
.sentinela-sim-kpi-approval { border-top-color: #7d6229; background: #fdfaf2; }
.sentinela-sim-kpi-warn { border-top-color: #b8511f; }
.sentinela-sim-kpi-xalteca { border-top-color: #1a5582; }

.sentinela-sim-kpi-label {
    color: #5a6478;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}

.sentinela-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}

.sentinela-sim-briefing {
    background: #ffffff;
    border: 1px solid #e1e4ea;
    border-left: 4px solid #c9a04d;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-radius: 3px;
}

.sentinela-sim-briefing-title {
    font-size: 1.05rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 10px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.sentinela-sim-briefing-body {
    color: #2c3548;
    font-size: 0.92rem;
    line-height: 1.55;
}

.sentinela-sim-briefing-body strong {
    color: #1a2744;
    font-weight: 700;
}

.sentinela-sim-controls {
    background: #ffffff;
    border: 1px solid #e1e4ea;
    padding: 24px 28px;
    border-radius: 3px;
    margin-bottom: 24px;
}

.sentinela-sim-controls h3 {
    color: #1a2744;
    font-size: 0.95rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid #e1e4ea;
}

.sentinela-sim-decision-panel {
    margin-bottom: 16px;
}

.sentinela-sim-decision-row {
    margin-bottom: 14px;
}

.sentinela-sim-decision-row label {
    display: block;
    color: #1a2744;
    font-size: 0.78rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
}

.sentinela-sim-controls select,
.sentinela-sim-controls input[type="number"],
.sentinela-sim-controls input[type="text"] {
    background: #ffffff;
    border: 1px solid #c8cdd6;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
}

.sentinela-sim-controls select:focus,
.sentinela-sim-controls input:focus {
    outline: none;
    border-color: #7d6229;
    box-shadow: 0 0 0 3px rgba(201,160,77,0.15);
}

.sentinela-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}

.sentinela-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid #e1e4ea;
}

.sentinela-sim-actions .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    padding: 10px 24px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.85rem;
    border-radius: 3px;
}

.sentinela-sim-actions .btn-primary:hover {
    background: #c9a04d;
    border-color: #7d6229;
    color: #1a2744;
}

.sentinela-sim-actions .btn-outline-secondary {
    border-color: #c8cdd6;
    color: #5a6478;
    padding: 10px 16px;
    font-weight: 500;
    font-size: 0.8rem;
    border-radius: 3px;
}

.sentinela-sim-history {
    background: #ffffff;
    border: 1px solid #e1e4ea;
    padding: 22px 26px;
    border-radius: 3px;
    margin-bottom: 24px;
}

.sentinela-sim-history h3 {
    color: #1a2744;
    font-size: 0.95rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 14px 0;
}

.sentinela-sim-history table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.85rem;
}

.sentinela-sim-history table th {
    background: #f4f5f7;
    color: #1a2744;
    padding: 10px 12px;
    text-align: left;
    font-weight: 700;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 2px solid #1a2744;
}

.sentinela-sim-history table td {
    padding: 10px 12px;
    color: #2c3548;
    border-bottom: 1px solid #e1e4ea;
    vertical-align: top;
}

.sentinela-sim-history table tr:hover td {
    background: #fafbfd;
}

.sentinela-sim-chart {
    background: #ffffff;
    border: 1px solid #e1e4ea;
    padding: 24px 28px;
    border-radius: 3px;
    height: 380px;
}

@media (max-width: 768px) {
    .sentinela-sim-container { padding: 16px; }
    .sentinela-sim-header { flex-direction: column; align-items: flex-start; gap: 16px; }
    .sentinela-sim-roundmeta { text-align: left; }
    .sentinela-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .sentinela-sim-kpi-grid-secondary { grid-template-columns: 1fr; }
    .sentinela-sim-actions { flex-direction: column; align-items: stretch; }
}


/* --- EQIL additions (adapter 1.1.0) --- */
.sentinela-sim-analysis {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-left: 4px solid #1a2744;
    border-radius: 4px;
    padding: 16px 20px;
    margin-bottom: 18px;
}
.sentinela-sim-analysis-label {
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #5a6274;
    font-weight: 600;
    margin-bottom: 6px;
}
.sentinela-sim-analysis-body { font-size: 0.93rem; line-height: 1.6; color: #1a2744; }
.sentinela-sim-analysis-body ul { margin: 0; padding-left: 20px; }
.sentinela-sim-analysis-body li { margin-bottom: 6px; }
.sentinela-sim-complete-banner {
    margin: 12px 0;
    padding: 12px 16px;
    border-radius: 4px;
    border: 1px solid #1a2744;
    background: #eef1f6;
    color: #1a2744;
    font-weight: 600;
}
button:focus-visible, select:focus-visible, input:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sentinela-sim-shell *, .sentinela-sim-analysis {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

