                } else {
                    archScore += 0;
                    commentary = 'cm_r2_name_lite';
                }

                if (cont === 'hard') {
                    archScore += 20;
                    cannibal = 1.3;
                } else if (cont === 'medium') {
                    archScore += 10;
                    cannibal = 4.0;
                    commentary += (commentary ? '|' : '') + 'cm_r2_cont_medium';
                } else {
                    archScore += 0;
                    cannibal = 8.5;
                    commentary += (commentary ? '|' : '') + 'cm_r2_cont_soft';
                }
                if (!commentary) commentary = 'cm_r2_textbook';
            } else if (arch === 'branded-house') {
                archScore = 30;
                cannibal = 0;
                commentary = 'cm_r2_branded_house';
            } else if (arch === 'endorsed') {
                archScore = 55;
                cannibal = 5.5;
                commentary = 'cm_r2_endorsed';
            } else {
                archScore = 20;
                cannibal = 12.0;
                commentary = 'cm_r2_house';
            }

            ds.archScore = archScore;
            ds.cannibalisationPct = cannibal;
            ds.approvalLevel = Math.round(((ds.evaScore || 0) + archScore) / 2);
            ds.log.push('R2: archetype=' + arch + ', name=' + name + ', containment=' + cont);

            return {
                period: 2,
                archetype: arch,
                subbrandName: name,
                containment: cont,
                archScore: archScore,
                cannibalisationPct: cannibal,
                commentary: commentary
            };
        }

        _scoreRound3(d, ds) {
            var strat = d.xaltecaStrategy;
            var term = d.contractTerm;
            var script = d.poisoningScript;
            var defScore = 0;
            var xaltecaRetainedPct = 0;
            var xaltecaBaselineARR = 38;
            var poisoning = 0;
            var commentary = '';

            if (strat === 'mix-shift') {
                defScore = 70;
                xaltecaRetainedPct = 86;
                commentary = 'cm_r3_mix';
            } else if (strat === 'price-match') {
                defScore = 30;
                xaltecaRetainedPct = 100;
                poisoning += 60;
                commentary = 'cm_r3_match';
            } else if (strat === 'defend') {
                defScore = 25;
                xaltecaRetainedPct = 0;
                commentary = 'cm_r3_defend';
            } else {
                defScore = 35;
                xaltecaRetainedPct = 0;
                commentary = 'cm_r3_abandon';
            }

            if (strat === 'mix-shift') {
                if (term === '5') defScore += 15;
                else if (term === '3') defScore += 8;
                else defScore += 5;
            }

            if (script === 'different-product') {
                poisoning = Math.max(0, poisoning - 10);
                if (strat === 'mix-shift') defScore += 15;
            } else if (script === 'discount') {
                poisoning += 25;
                commentary += '|cm_r3_script_discount';
            } else {
                poisoning += 50;
                commentary += '|cm_r3_script_none';
            }

            poisoning = Math.min(100, Math.max(0, poisoning));
            defScore = Math.min(100, defScore);

            ds.defenseScore = defScore;
            ds.poisoningRisk = poisoning;
            ds.xaltecaARRRetained = Math.round(xaltecaBaselineARR * xaltecaRetainedPct / 100);

            var finalApproval = Math.round(0.30 * (ds.evaScore || 0) + 0.30 * (ds.archScore || 0) + 0.40 * defScore);
            finalApproval -= Math.round(poisoning * 0.3);
            finalApproval = Math.max(0, Math.min(100, finalApproval));
            ds.approvalLevel = finalApproval;
            ds.log.push('R3: strat=' + strat + ', term=' + term + ', script=' + script + ', retained=$' + ds.xaltecaARRRetained + 'M');

            return {
                period: 3,
                xaltecaStrategy: strat,
                contractTerm: term,
                poisoningScript: script,
                defenseScore: defScore,
                xaltecaARRRetained: ds.xaltecaARRRetained,
                poisoningRisk: poisoning,
                finalApproval: finalApproval,
                commentary: commentary
            };
        }

