        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var roundScoreTotal = (ds.evaScore || 0) + (ds.archScore || 0) + (ds.defenseScore || 0);
            var composite = this._composite(ds);
            var band = this._band(composite);
            var labels = {
                excellent:  this._L('Outstanding - Roberto reads the memo over breakfast', 'Sobresaliente - Roberto lee el memorando en el desayuno'),
                good:       this._L('Excellent - Andres signs off Friday', 'Excelente - Andrés lo aprueba el viernes'),
                developing: this._L('Acceptable - rollout plan needs rework', 'Aceptable - el plan de lanzamiento necesita revisión'),
                needs_work: this._L('Marginal - Andres escalates to Roberto', 'Insuficiente - Andrés lo escala a Roberto')
            };
            var insights = [];
            if ((ds.cannibalisationPct || 0) > 5) {
                insights.push(this._L('Cannibalisation drag exceeds 5% - fighter brand containment broke down.',
                                      'La canibalización supera el 5%: la contención de la marca de combate falló.'));
            }
            if ((ds.poisoningRisk || 0) > 50) {
                insights.push(this._L('Channel poisoning risk above 50 - Tupiara and Valdora parity calls within ninety days.',
                                      'Riesgo de contaminación de canal por encima de 50: llamadas de paridad de Tupiara y Valdora en noventa días.'));
            }
            if ((ds.xaltecaARRRetained || 0) >= 30) {
                insights.push(this._L('Xalteca retained at credible terms - franchise customer preserved.',
                                      'Xalteca retenido en condiciones creíbles: cliente insignia preservado.'));
            }
            if ((ds.evaScore || 0) >= 85) {
                insights.push(this._L('EVA case made the lower-bound argument - economic justification clears the bar.',
                                      'El caso EVA planteó el argumento de límite inferior: la justificación económica supera el umbral.'));
            }
            if (!insights.length) {
                insights.push(this._L('Re-read the four fighter-brand diagnostic conditions and try again.',
                                      'Vuelve a leer las cuatro condiciones de diagnóstico de marca de combate e inténtalo de nuevo.'));
            }

            return {
                roundScoreTotal: roundScoreTotal,
                evaScore: ds.evaScore,
                archScore: ds.archScore,
                defenseScore: ds.defenseScore,
                xaltecaARRRetained: ds.xaltecaARRRetained,
                cannibalisationPct: ds.cannibalisationPct,
                poisoningRisk: ds.poisoningRisk,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: band,
                performanceKey: band,
                performanceLabel: labels[band],
                insights: insights
            };
        }

